def transform(grid):
    h,w=len(grid),len(grid[0])
    out=[[0]*w for _ in range(h)]
    seen=set()
    for r in range(h):
        for c in range(w):
            if not grid[r][c] or (r,c) in seen: continue
            stack=[(r,c)]; seen.add((r,c)); comp=[]
            while stack:
                y,x=stack.pop(); comp.append((y,x))
                for dy,dx in ((1,0),(-1,0),(0,1),(0,-1)):
                    a,b=y+dy,x+dx
                    if 0<=a<h and 0<=b<w and grid[a][b] and (a,b) not in seen:
                        seen.add((a,b)); stack.append((a,b))
            shift=w-1-max(x for y,x in comp)
            for y,x in comp: out[y][x+shift]=grid[y][x]
    return out

